<?php
require_once __DIR__.'/../core/Auth.php';
require_once __DIR__.'/../core/Database.php';
require_once __DIR__.'/../core/Response.php';
require_once __DIR__.'/../core/JalaliDate.php';
require_once __DIR__.'/../services/WorkPlannerService.php';
Auth::requireLogin();
$user=Auth::user();$userId=(int)$user['id'];
$redirect='/employee/work-planner.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار فرم منقضی شده است. دوباره تلاش کنید.','danger');redirect($redirect);}
    try{
        $action=(string)($_POST['action']??'');$taskId=(int)($_POST['task_id']??0);
        if($action==='create'){
            $title=trim((string)($_POST['title']??''));if($title==='')throw new InvalidArgumentException('عنوان وظیفه الزامی است.');
            $returnDate=JalaliDate::toGregorian((string)($_POST['return_date']??''))?:trim((string)($_POST['return_date']??''));$due=JalaliDate::toGregorian((string)($_POST['due_date']??''))?:$returnDate;if(!$due)$due=date('Y-m-d');$input=$_POST;$input['due_date']=$due;WorkPlannerService::createPersonalTask($userId,$input,$due);flash('وظیفه افزوده شد.');
        }elseif($action==='edit'){
            $input=$_POST;$input['due_date']=JalaliDate::toGregorian((string)($_POST['due_date']??''))?:null;if(!WorkPlannerService::updatePersonalTask($taskId,$input,$userId))throw new InvalidArgumentException('این وظیفه قابل ویرایش نیست.');flash('وظیفه ویرایش شد.');
        }elseif($action==='status'){
            if(!WorkPlannerService::updateTaskStatus($taskId,(string)($_POST['status']??''),$userId))throw new InvalidArgumentException('تغییر وضعیت مجاز نیست.');flash('وضعیت وظیفه ثبت شد.');
        }elseif($action==='tomorrow'){
            if(!WorkPlannerService::moveToTomorrow($taskId,$userId))throw new InvalidArgumentException('انتقال این وظیفه ممکن نیست.');flash('مهلت وظیفه یک روز جلو رفت.');
        }elseif($action==='generate'){
            $matchingTemplates=WorkPlannerService::matchingTemplatesForUser($userId);
            if(!$matchingTemplates)flash('برای تولید خودکار، ابتدا نقش یا واحد سازمانی شما باید در ساختار سازمانی تنظیم شود.','warning');
            else{$count=WorkPlannerService::generateDailyTasksForUser($userId,date('Y-m-d'));flash($count?'تعداد '.$count.' وظیفه نقش‌محور ساخته شد.':'قالب جدیدی برای برنامه امروز شما وجود نداشت.');}
        }
    }catch(InvalidArgumentException|DomainException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Personal work planner: '.$e->getMessage());flash('عملیات پلنر انجام نشد. لطفاً دوباره تلاش کنید.','danger');}
    $returnDate=JalaliDate::toGregorian((string)($_POST['return_date']??''))?:($_POST['return_date']??null);redirect($redirect.'?'.http_build_query(array_filter(['view'=>$_POST['return_view']??null,'date'=>$returnDate])));
}
$view=in_array($_GET['view']??'',['daily','weekly','monthly','list'],true)?$_GET['view']:'daily';$requested=trim((string)($_GET['date']??date('Y-m-d')));$anchor=JalaliDate::toGregorian($requested)?:$requested;try{$day=new DateTimeImmutable($anchor);}catch(Throwable){$day=new DateTimeImmutable('today');}$anchor=$day->format('Y-m-d');
$where=['t.user_id=?'];$params=[$userId];$from=$to=null;
if($view==='daily')$from=$to=$anchor;
elseif($view==='weekly'){$from=$day->modify('-'.(((int)$day->format('w')+1)%7).' days')->format('Y-m-d');$to=(new DateTimeImmutable($from))->modify('+6 days')->format('Y-m-d');}
elseif($view==='monthly'){$from=$day->modify('first day of this month')->format('Y-m-d');$to=$day->modify('last day of this month')->format('Y-m-d');}
if($from){$where[]='t.due_date BETWEEN ? AND ?';$params[]=$from;$params[]=$to;}
WorkPlannerService::ensureOccurrencesForUser($userId,$from?:$anchor,$to?:$day->modify('+1 year')->format('Y-m-d'));
$tasks=Database::fetchAll('SELECT t.*,o.title okr_title FROM work_planner_tasks t LEFT JOIN okr_objectives o ON t.related_module="okr" AND o.id=t.related_record_id WHERE '.implode(' AND ',$where).' ORDER BY CASE WHEN t.status="in_progress" THEN 0 WHEN t.due_date<CURDATE() AND t.status NOT IN("done","cancelled") THEN 1 ELSE 2 END,FIELD(t.priority,"urgent","high","normal","low"),t.due_date,t.id DESC',$params);
$matchingTemplates=WorkPlannerService::matchingTemplatesForUser($userId);$hasMatchingTemplates=(bool)$matchingTemplates;$isToday=$view==='daily'&&$anchor===date('Y-m-d');
$pageTitle='برنامه کاری من';$adminExtraStylesheets=['/assets/css/personal-planner.css'];require __DIR__.'/../views/partials/admin-header.php';
?>
<div class="section-heading-row"><div><h1>برنامه کاری من</h1><p class="muted">پلنر شخصی شما؛ مستقل از فعال بودن پنل کارمندی</p></div><?php if($hasMatchingTemplates):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="generate"><input type="hidden" name="return_view" value="<?=e($view)?>"><input type="hidden" name="return_date" value="<?=e($anchor)?>"><button class="btn">تولید وظایف نقش امروز</button></form><?php else:?><p class="muted">تولید خودکار پس از تنظیم نقش یا واحد سازمانی فعال می‌شود.</p><?php endif?></div>
<nav class="planner-tabs" aria-label="نمای پلنر"><a class="btn" href="?view=daily&date=<?=e($day->modify('-1 day')->format('Y-m-d'))?>">دیروز</a><a class="btn <?=$view==='daily'&&$anchor===date('Y-m-d')?'btn-primary':''?>" href="?view=daily&date=<?=e(date('Y-m-d'))?>">امروز</a><a class="btn" href="?view=daily&date=<?=e($day->modify('+1 day')->format('Y-m-d'))?>">فردا</a><?php foreach(['weekly'=>'هفتگی','monthly'=>'ماهانه','list'=>'فهرست'] as $key=>$label):?><a class="btn <?=$view===$key?'btn-primary':''?>" href="?view=<?=$key?>&date=<?=e($anchor)?>"><?=e($label)?></a><?php endforeach?></nav>
<form class="card filter-form" method="get"><input type="hidden" name="view" value="<?=e($view)?>"><label>تاریخ مبنا<input class="jalali-date-input" name="date" inputmode="numeric" value="<?=e(JalaliDate::toJalali($anchor))?>"></label><button class="btn">نمایش</button></form>
<section class="card admin-form planner-daily-quick-add"><details open><summary><strong>افزودن وظیفه امروز</strong></summary><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="create"><input type="hidden" name="return_view" value="<?=e($view)?>"><input type="hidden" name="return_date" value="<?=e($anchor)?>"><div class="grid grid-3"><label class="form-field"><span>عنوان</span><input name="title" required maxlength="190"></label><label class="form-field"><span>مهلت</span><input class="jalali-date-input" name="due_date" value="<?=e(JalaliDate::toJalali($anchor))?>"></label><label class="form-field"><span>اولویت</span><select name="priority"><option value="normal">عادی</option><option value="high">بالا</option><option value="urgent">فوری</option><option value="low">کم</option></select></label><label class="form-field"><span>تکرار</span><select name="recurrence_type"><option value="none">بدون تکرار</option><option value="daily">روزانه</option><option value="weekly">هفتگی</option><option value="monthly">ماهانه</option></select></label><label class="form-field"><span>هر چند دوره</span><input type="number" name="recurrence_interval" min="1" max="365" value="1"></label><label class="form-field"><span>شرح</span><input name="description" maxlength="1000"></label></div><button class="btn btn-primary">افزودن</button></form></details></section>
<section class="planner-board planner-view-<?=e($view)?>"><?php foreach($tasks as $task):?><article class="card planner-task-card"><header><div><span class="badge"><?=e(work_planner_priority_label($task['priority']))?></span><?php if(($task['recurrence_type']??'none')!=='none'):?><span class="badge">تکرارشونده</span><?php endif?></div><small><?=e($task['due_date']?format_jalali_date($task['due_date']):'بدون مهلت')?></small></header><h2><?=e($task['title'])?></h2><?php if(($task['related_module']??'')==='okr'&&!empty($task['okr_title'])):?><p><a href="/admin/okr-objective.php?id=<?=e((string)$task['related_record_id'])?>">مرتبط با OKR: <?=e($task['okr_title'])?></a></p><?php elseif(in_array(($task['related_module']??''),['action','actions','action_hub'],true)&&!empty($task['related_record_id'])):?><p><a href="/admin/action-view.php?id=<?=e((string)$task['related_record_id'])?>">مشاهده اقدام مرتبط</a></p><?php endif?><?php if($task['description']):?><p><?=e($task['description'])?></p><?php endif?><p class="muted"><?=e(work_planner_status_label($task['status']))?></p><div class="form-actions"><?php if($task['status']==='todo'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="task_id" value="<?=$task['id']?>"><input type="hidden" name="status" value="in_progress"><button class="btn btn-small">شروع</button></form><?php elseif($task['status']==='in_progress'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="task_id" value="<?=$task['id']?>"><input type="hidden" name="status" value="todo"><button class="btn btn-small">مکث</button></form><?php endif?><?php if(!in_array($task['status'],['done','cancelled'],true)):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="task_id" value="<?=$task['id']?>"><input type="hidden" name="status" value="done"><button class="btn btn-small btn-primary">انجام شد</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="tomorrow"><input type="hidden" name="task_id" value="<?=$task['id']?>"><button class="btn btn-small">انتقال به فردا</button></form><?php endif?></div><?php if((int)$task['is_personal']):?><details><summary>ویرایش</summary><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="edit"><input type="hidden" name="task_id" value="<?=$task['id']?>"><label>عنوان<input name="title" value="<?=e($task['title'])?>" required></label><label>شرح<textarea name="description"><?=e($task['description'])?></textarea></label><label>مهلت<input class="jalali-date-input" name="due_date" value="<?=e(JalaliDate::toJalali($task['due_date']))?>"></label><label>اولویت<select name="priority"><?php foreach(['low'=>'کم','normal'=>'عادی','high'=>'بالا','urgent'=>'فوری'] as $key=>$label):?><option value="<?=$key?>" <?=$task['priority']===$key?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label>تکرار<select name="recurrence_type"><?php foreach(['none'=>'بدون تکرار','daily'=>'روزانه','weekly'=>'هفتگی','monthly'=>'ماهانه'] as $key=>$label):?><option value="<?=$key?>" <?=($task['recurrence_type']??'none')===$key?'selected':''?>><?=$label?></option><?php endforeach?></select></label><input type="number" name="recurrence_interval" min="1" max="365" value="<?=e((string)($task['recurrence_interval']??1))?>"><button class="btn btn-small">ذخیره</button></form></details><?php endif?></article><?php endforeach?><?php if(!$tasks):?><div class="card"><h2>در این بازه وظیفه‌ای ندارید.</h2><?php if($isToday&&$hasMatchingTemplates):?><p>می‌توانید وظایف نقش امروز را از دکمه بالای صفحه تولید کنید یا از فرم «افزودن وظیفه امروز» یک کار شخصی بسازید.</p><?php elseif($isToday):?><p>قالب نقش‌محور متناسب با حساب شما یافت نشد. برای تولید خودکار، نقش یا واحد سازمانی باید تنظیم شود؛ تا آن زمان می‌توانید از فرم بالا وظیفه شخصی بسازید.</p><?php else:?><p>تاریخ یا نما را تغییر دهید، یا از فرم بالا یک وظیفه شخصی برای این تاریخ بسازید.</p><?php endif?></div><?php endif?></section>
<?php require __DIR__.'/../views/partials/admin-footer.php';
